# AI Office v2.6 Part E Live Conversational Memory Integration Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.6-part-e-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)
    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination
    if ($Parent) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath
        if ($BackupParent) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }
    [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\memory\live-integration-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeConversationMemoryContext.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Add-AIOfficeMemoryContextToPrompt.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Test-AIOfficeLiveConversationalMemoryIntegration.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.6-Part-E-Live-Conversational-Memory-Integration.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1" -Base64Content ""
$Scripts = @(
"E:\AI\AI-Office\scripts\memory\Get-AIOfficeConversationMemoryContext.ps1",
"E:\AI\AI-Office\scripts\memory\Add-AIOfficeMemoryContextToPrompt.ps1",
"E:\AI\AI-Office\scripts\memory\Test-AIOfficeLiveConversationalMemoryIntegration.ps1",
"E:\AI\AI-Office\scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1"
)
foreach ($Script in $Scripts) {
  $Tokens=$null; $ParseErrors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
  if ($ParseErrors.Count -gt 0) {
    throw ("Syntax error in " + $Script + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; "))
  }
}
Write-Host ""
Write-Host "AI Office v2.6 Part E Live Conversational Memory Integration installed successfully." -ForegroundColor Green
Write-Host "Relevant durable memory is now wired into the conversational runtime with memory-free fallback." -ForegroundColor Cyan
Write-Host "Restart the Discord worker only after Part E certification passes." -ForegroundColor Yellow
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan